        $IPAddress = $IPAddress.split('::ffff:')[-1]
      }
      $TGT += [PSCustomObject]@{'TimeStamp' = $TimeStamp; 'TargetUserName' = $TargetUserName; 'IPAddress' = $IPAddress }
    }
  }
  End {
    return $TGT
  }
}
