    Process {
        # ドメイン名を含むセッション情報を抽出し、ログオンIDとユーザー名をオブジェクト化
        $Sessions = $Klist | Where-Object { $_ -like "*Session*$env:USERDOMAIN*" } | ForEach-Object { 
