# 2. 抽出されたセッションに盗まれたチケットが注入されていないか検証する関数
Function Invoke-PTTSweep {
    [CmdletBinding()]
    Param (
        [Parameter(ValueFromPipeline = $true)]
        $Session
    )
    Begin {
        $Flagged = @()
    }
    Process {
        # セッション情報から「想定されるユーザー名」と「ログオンID」を抽出
        $LogonId = $($Session.LogonId)
        $Expected = $(($Session.User).Split('\')[1]).Trim()

        # klistコマンドを使用して、そのセッション内のTGT（チケット）の所有者（Actual）を抽出
        # ※^#0 は最初のチケット（通常はTGT）を指す
        $KlistOutput = klist -li $LogonId
        $TicketInfo = $KlistOutput | Select-String '^#0'

        if ($TicketInfo) {
            # チケット内の Client 名をパースして取得
            $Actual = ((($TicketInfo -split 'Client: ')[1] -split '@')[0]).Trim()

            # 想定されるユーザー(セッション所有者)と、実際のチケット所有者が一致するか比較
            if ($Expected -ne $Actual) {
                # コンピュータアカウントによる正当なセッションでないことを確認
                if ($Actual -ne "$env:computername$") {
                    # 一致しない場合は、異常なセッションとして情報を記録
                    $Flagged += [PSCustomObject]@{
                        'LogonId'     = $LogonId
                        'SessionUser' = $Expected
                        'TGTUser'     = $Actual
                    }
                }
            }
        }
    }
    End {
        # 異常が見つかったセッションの一覧を返す
        return $Flagged
    }
}

# 実行方法の例:
# Get-SessionUsers | Invoke-PTTSweep
